                return idx < 3 || std::find(points.begin(), points.end(), superTriangle[idx - 3]) != points.end();
            })) {
                if (isPointInTriangle(points[i], superTriangle[triangle[0] < 3 ? triangle[0] : triangle[0] - 3],
                                     superTriangle[triangle[1] < 3 ? triangle[1] : triangle[1] - 3],
                                     superTriangle[triangle[2] < 3 ? triangle[2] : triangle[2] - 3])) {
                    badTriangles.push_back(triangle);
                }
            }
        }

        // Collect boundary edges of bad triangles
        for (const auto& triangle : badTriangles) {
            for (std::size_t j = 0; j < 3; ++j) {
                std::size_t k = (j + 1) % 3;
                std::size_t idx1 = triangle[j] < 3 ? triangle[j] : triangle[j] - 3;
                std::size_t idx2 = triangle[k] < 3 ? triangle[k] : triangle[k] - 3;
                if (std::find(polygon.begin(), polygon.end(), idx1) == polygon.end()) {
                    polygon.push_back(idx1);
                }
                if (std::find(polygon.begin(), polygon.end(), idx2) == polygon.end()) {
                    polygon.push_back(idx2);
                }
            }
        }

        // Remove bad triangles
        triangles.erase(std::remove_if(triangles.begin(), triangles.end(),
            [&](const std::vector<std::size_t>& t) {
                return std::find(badTriangles.begin(), badTriangles.end(), t) != badTriangles.end();
            }), triangles.end());

        // Create new triangles from polygon and new point
        for (std::size_t j = 0; j < polygon.size(); ++j) {
            std::size_t k = (j + 1) % polygon.size();
            triangles.push_back({polygon[j], polygon[k], i});
        }
    }

    // Remove triangles containing super triangle vertices
    triangles.erase(std::remove_if(triangles.begin(), triangles.end(),
        [&](const std::vector<std::size_t>& t) {
            return std::any_of(t.begin(), t.end(), [](std::size_t idx) { return idx < 3; });
        }), triangles.end());

    return triangles;

